import{z as l,x as s,o,c as n,q as d,j as r,D as a,d as t,s as E,S as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"指针与别名","description":"","frontmatter":{"title":"指针与别名","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pointer-alias.md","filePath":"cs/pointer-alias.md","lastUpdated":1791413859000}'),p={name:"cs/pointer-alias.md"};function A(B,e,m,h,C,_){const c=s("Mermaid");return o(),n("div",null,[e[2]||(e[2]=d('<h1 id="指针与别名" tabindex="-1">指针与别名 <a class="header-anchor" href="#指针与别名" aria-label="Permalink to &quot;指针与别名&quot;">​</a></h1><div class="epigraph"><p>指针保存的是对象的地址；两个指针若指向同一对象，通过其中一个写入，另一个立刻看见——优化必须把这种可能算进去。</p><footer>—— 据 Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；ISO/IEC 9899；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 整理</footer></div><p>上一课<a href="/cs/stack-heap-static">栈、堆与静态存储</a>把三种寿命钉在三片区域上。本课不重讲 <code>malloc</code>，也不从类型论另起。缺口是：区域里的对象已经有名字，<strong>指针可以再制造跨作用域的名字</strong>。同一块存储多个视图时，读写通过谁发生？编译器何时不能假定「这两个指针绝不重叠」？</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 里指针是对象的地址值。<code>&amp;x</code> 取址，<code>*p</code> 解引用，指针赋值把同一视图交给别人。若 <code>p</code> 与 <code>q</code> 都指向 <code>x</code>，则 <code>*p = 1</code> 与 <code>*q = 2</code> 写的是同一存储。<span class="marginnote">把指针想成「写着门牌号的纸条」：<code>&amp;x</code> 是抄下 x 家的门牌号，<code>*p</code> 解引用就是「顺着纸条上的门牌号找上门去」，读或写那间房子里的东西。别名则是同一间房有两张纸条——从哪张纸条找过去，改的都是同一间房，这就是「写入立刻互相看见」的原因。</span>缺口因此不是 <code>*</code> 的语法，而是<strong>别名对语义与优化的约束</strong>：未声明 <code>restrict</code> 时，通过指针的写可能改掉「看似无关」的自动变量或全局。后课的未定义行为、悬挂，都先要承认「地址可以共享」。</p><p>传参默认按值：指针本身被拷贝，指向的对象不拷贝。这让 callee 能改 caller 的栈对象或堆块，而不必把结构体整份搬进帧。链表、树、输出参数都靠这一条。本课只钉「指向对象」；数组表达式为何常常变成指针，是<a href="/cs/array-decay">下一课</a>。</p><h3 id="指针不是整数" tabindex="-1">指针不是整数 <a class="header-anchor" href="#指针不是整数" aria-label="Permalink to &quot;指针不是整数&quot;">​</a></h3><p>调试时可以把地址印成整数，但指针算术与比较受对象类型和对象边界约束。把任意整数转换成指针再解引用，是<a href="/cs/undefined-behavior">未定义行为</a>的入口，不是「底层很自由」。本课语义里，指针首先是指向某个活着的对象，不是机器字上的无符号算术。</p><p><span class="marginnote">K&amp;R 用指针把数组、字符串与函数参数串起来。ISO C 的有效类型与别名规则约束「用哪种类型的左值去读这块存储」。CSAPP 把指针当地址，但立刻强调越界与类型错误会离开抽象机器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>int *p</code> 表示 <code>p</code> 保存某个 <code>int</code> 对象的地址，<code>*p</code> 是该对象的左值。指针参数把 caller 与 callee 绑到同一存储。<code>void *</code> 可以携带任意对象地址，但不携带类型；解引用前必须转回实际类型。空指针不指向任何对象，解引用它是 UB。</p>',11)),(o(),r(i,null,{default:a(()=>[E(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E5%AF%B9%E8%B1%A1%20x%22%5D%20--%3E%20P%5B%22p%20%E7%AD%89%E4%BA%8E%20x%20%E7%9A%84%E5%9C%B0%E5%9D%80%22%5D%0A%20%20P%20--%3E%20Q%5B%22q%20%E7%AD%89%E4%BA%8E%20p%22%5D%0A%20%20Q%20--%3E%20W%5B%22%E9%80%9A%E8%BF%87%20q%20%E5%86%99%E5%85%A5%22%5D%0A%20%20W%20--%3E%20X%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<p>两个指针是否别名，编译器在一般函数里无法静态看穿。于是它必须保守：不能把 <code>*p</code> 的旧值缓存过一次 <code>*q</code> 的写入。<code>restrict</code> 是程序员对「不重叠」的承诺，本课只点名，不把优化器内部展开。</p><p>函数若接受两个指针参数，文档必须声明它们是否允许重叠：<code>memcpy</code> 禁止，<code>memmove</code> 允许。这是别名写进契约的样板。<span class="marginnote">为什么重叠时 <code>memcpy</code> 会出事？具体看一例：把 <code>a[0..3]</code> 向后挪一格拷到 <code>a[1..4]</code>，若从前往后逐字节拷，第 1 步把 <code>a[0]</code> 写进 <code>a[1]</code>，第 2 步要读的 <code>a[1]</code> 已经被盖掉了——拷出来全错。<code>memmove</code> 会先判断重叠方向、从后往前拷（或先拷进临时缓冲），所以慢一点但允许重叠。初学者容易以为两者「随便换用」，重叠时 <code>memcpy</code> 是未定义行为。</span>实现可以用 <code>restrict</code> 让编译器按不重叠优化，一旦调用方违反，又是 UB。后课数组衰减会让 <code>int a[]</code> 与 <code>int *</code> 在参数上变成同一件事，别名分析看见的是指针，不是「数组对象不能重叠」的幻想。先把对象与指向它的指针分清，衰减才好讲。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>别名让「局部变量没人改」不再自动成立。一次通过指针的存储，可能让另一条看似无关的读必须重新从内存取。这不是编译器笨，是语言允许共享。<span class="marginnote">代价可以量化：本来一次 <code>*p</code> 读进寄存器后可反复复用，别名一旦无法排除，每次写 <code>*q</code> 之前都得重新 load——内层循环里每个元素从 1 次访存变 2 次，热循环吞吐可能直接腰斩。这就是 <code>restrict</code> 这个关键字存在的全部理由：把「不会重叠」变成可兑现的优化承诺。</span>反过来，若程序保证两路指针永不重叠，却不告诉编译器，就会留下本可去掉的 load。</p>',4)),(o(),r(i,null,{default:a(()=>[E(c,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%E6%83%B3%E6%8A%8A%E8%AF%BB%E8%BF%87%E7%9A%84%20*p%20%E7%BC%93%E5%AD%98%E5%9C%A8%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20Q%7B%22%E4%B8%AD%E9%97%B4%E7%BB%8F%E8%BF%87%E7%9A%84%E5%86%99%E5%85%A5%E4%BC%9A%E4%B8%8D%E4%BC%9A%E6%94%B9%E5%88%B0%20*p%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%E8%83%BD%E8%AF%81%E6%98%8E%E4%B8%8D%E4%BC%9A%7C%20KEEP%5B%22%E6%94%BE%E5%BF%83%E5%A4%8D%E7%94%A8%E7%BC%93%E5%AD%98%E5%80%BC%EF%BC%8C%E7%9C%81%E4%B8%80%E6%AC%A1%E8%AE%BF%E5%AD%98%22%5D%0A%20%20Q%20--%3E%7C%E6%97%A0%E6%B3%95%E6%8E%92%E9%99%A4%E5%88%AB%E5%90%8D%7C%20RE%5B%22%E4%B8%A2%E5%BC%83%E7%BC%93%E5%AD%98%EF%BC%9A%E6%AF%8F%E6%AC%A1%E5%86%99%E5%85%A5%E5%90%8E%E9%87%8D%E6%96%B0%20load%22%5D%0A%20%20RE%20--%3E%20COST%5B%22%E4%BF%9D%E5%AE%88%E6%AD%A3%E7%A1%AE%EF%BC%8C%E4%BD%86%E7%83%AD%E5%BE%AA%E7%8E%AF%E5%8F%98%E6%85%A2%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p>堆上尤其如此：<code>malloc</code> 返回的地址进入多个指针变量之后，释放与再分配会让<strong>同一数值地址</strong>稍后属于另一个对象。别名是空间上的重叠；悬挂是时间上的错位。本课先把空间重叠钉死。</p><p>别名也解释了为何「看起来没人写的局部变量」在优化报告里仍被反复加载：只要存在一个可能指向它的指针参数，编译器就必须假定一次未知存储会改掉它。<code>restrict</code> 是把这个假定反过来写成程序员承诺，本课不把它当默认。结构体字段指针与数组元素指针都是同一机制的特例。后课未定义行为会把「用错类型的左值去读」也称为别名违规；这里先只要空间重叠这一层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开 strict aliasing 的逐条规则，也不讲整程序别名分析。数组与指针的互换见下一课。后课默认：指针表示活对象的地址；可能别名的指针限制优化；非法转换与空指针解引用属 UB。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指针保存地址；多指针可指向同一对象，写入立刻共享。</li><li>指针参数拷贝的是地址，不是对象；callee 能改 caller 的存储。</li><li>把指针当任意整数用会离开语言；<code>void *</code> 必须先恢复类型。</li><li>下一课处理数组在表达式里如何变成指针。</li><li>出处：K&amp;R；ISO C 有效类型；CSAPP 对指针即地址的程序员模型。</li></ul>',6))])}const f=l(p,[["render",A]]);export{u as __pageData,f as default};
